package hysteria

import (
	"bytes"
	"encoding/binary"
	go_errors "errors"
	"io"
	"math/rand"
	"testing"

	"github.com/apernet/quic-go"
	"github.com/apernet/quic-go/quicvarint"
	"github.com/xtls/xray-core/common/buf"
	xnet "github.com/xtls/xray-core/common/net"
)

const benchAddr = "203.0.113.1:53"

func benchMessage() []byte {
	m := &UDPMessage{PacketID: 1, FragCount: 1, Addr: benchAddr, Data: make([]byte, 1200)}
	b := make([]byte, m.Size())
	return b[:m.Serialize(b)]
}

// oldParse is the parser from XTLS/Xray-core master before the port.
func oldParse(msg []byte) (*UDPMessage, error) {
	m := &UDPMessage{}
	b := bytes.NewBuffer(msg)
	if err := binary.Read(b, binary.BigEndian, &m.SessionID); err != nil {
		return nil, err
	}
	if err := binary.Read(b, binary.BigEndian, &m.PacketID); err != nil {
		return nil, err
	}
	if err := binary.Read(b, binary.BigEndian, &m.FragID); err != nil {
		return nil, err
	}
	if err := binary.Read(b, binary.BigEndian, &m.FragCount); err != nil {
		return nil, err
	}
	lAddr, err := quicvarint.Read(b)
	if err != nil {
		return nil, err
	}
	if lAddr == 0 || lAddr > MaxMessageLength {
		return nil, go_errors.New("invalid address length")
	}
	bs := b.Bytes()
	if len(bs) <= int(lAddr) {
		return nil, go_errors.New("invalid message length")
	}
	m.Addr = string(bs[:lAddr])
	m.Data = bs[lAddr:]
	return m, nil
}

type oldUDPWriter struct {
	writer io.Writer
	addr   string
	buf    [buf.Size]byte
}

func (w *oldUDPWriter) SendMessage(msg *UDPMessage) error {
	msgN := msg.Serialize(w.buf[:])
	if msgN < 0 {
		return nil
	}
	_, err := w.writer.Write(w.buf[:msgN])
	return err
}

func (w *oldUDPWriter) WriteMultiBuffer(mb buf.MultiBuffer) error {
	for i, b := range mb {
		addr := w.addr
		if b.UDP != nil {
			addr = b.UDP.NetAddr()
		}
		msg := &UDPMessage{FragCount: 1, Addr: addr, Data: b.Bytes()}
		err := w.SendMessage(msg)
		var errTooLarge *quic.DatagramTooLargeError
		if go_errors.As(err, &errTooLarge) {
			msg.PacketID = uint16(rand.Intn(0xFFFF)) + 1
			fMsgs := FragUDPMessage(msg, int(errTooLarge.MaxDatagramPayloadSize))
			for _, fMsg := range fMsgs {
				if err := w.SendMessage(&fMsg); err != nil {
					buf.ReleaseMulti(mb[i:])
					return err
				}
			}
		} else if err != nil {
			buf.ReleaseMulti(mb[i:])
			return err
		}
		b.Release()
	}
	return nil
}

type oldUDPReader struct {
	reader io.Reader
	df     *Defragger
}

func (r *oldUDPReader) ReadFrom(p []byte) (int, *xnet.Destination, error) {
	for {
		var packet [1500]byte
		n, err := r.reader.Read(packet[:])
		if err != nil {
			return 0, nil, err
		}
		msg, err := oldParse(packet[:n])
		if err != nil {
			continue
		}
		dfMsg := r.df.Feed(msg)
		if dfMsg == nil {
			continue
		}
		dest, err := xnet.ParseDestination("udp:" + dfMsg.Addr)
		if err != nil {
			continue
		}
		if len(p) < len(dfMsg.Data) {
			continue
		}
		return copy(p, dfMsg.Data), &dest, nil
	}
}

func (r *oldUDPReader) ReadMultiBuffer() (buf.MultiBuffer, error) {
	b := buf.New()
	b.Resize(0, buf.Size)
	n, addr, err := r.ReadFrom(b.Bytes())
	if err != nil {
		b.Release()
		return nil, err
	}
	b.Resize(0, int32(n))
	b.UDP = addr
	return buf.MultiBuffer{b}, nil
}

type repeatReader struct {
	msg []byte
	off int
}

func (r *repeatReader) Read(p []byte) (int, error) {
	if r.off >= len(r.msg) {
		r.off = 0
	}
	n := copy(p, r.msg[r.off:])
	r.off += n
	return n, nil
}

func BenchmarkParseMessage(b *testing.B) {
	msg := benchMessage()
	b.Run("old", func(b *testing.B) {
		b.ReportAllocs()
		for b.Loop() {
			oldParse(msg)
		}
	})
	b.Run("new", func(b *testing.B) {
		b.ReportAllocs()
		for b.Loop() {
			ParseUDPMessage(msg)
		}
	})
	b.Run("new-reuse-addr", func(b *testing.B) {
		b.ReportAllocs()
		lastAddr := ""
		for b.Loop() {
			m, _ := ParseUDPMessageReuseAddr(msg, lastAddr)
			lastAddr = m.Addr
		}
	})
}

func benchWriter(b *testing.B, old bool) {
	b.Helper()
	bufr := buf.FromBytes(make([]byte, 1200))
	dest, err := xnet.ParseDestination("udp:" + benchAddr)
	if err != nil {
		b.Fatal(err)
	}
	bufr.UDP = &dest
	mb := buf.MultiBuffer{bufr}

	b.ReportAllocs()
	b.SetBytes(1200)
	if old {
		w := &oldUDPWriter{writer: io.Discard, addr: benchAddr}
		for b.Loop() {
			if err := w.WriteMultiBuffer(mb); err != nil {
				b.Fatal(err)
			}
		}
		return
	}
	w := &UDPWriter{writer: io.Discard, addr: benchAddr}
	for b.Loop() {
		if err := w.WriteMultiBuffer(mb); err != nil {
			b.Fatal(err)
		}
	}
}

func BenchmarkWriteMessage(b *testing.B) {
	b.Run("old", func(b *testing.B) { benchWriter(b, true) })
	b.Run("new", func(b *testing.B) { benchWriter(b, false) })
}

func BenchmarkReadMessage(b *testing.B) {
	msg := benchMessage()
	p := make([]byte, 65535)
	b.Run("old", func(b *testing.B) {
		r := &oldUDPReader{reader: &repeatReader{msg: msg}, df: &Defragger{}}
		b.ReportAllocs()
		b.SetBytes(int64(len(msg)))
		for b.Loop() {
			if _, _, err := r.ReadFrom(p); err != nil {
				b.Fatal(err)
			}
		}
	})
	b.Run("new", func(b *testing.B) {
		r := &UDPReader{reader: &repeatReader{msg: msg}, df: &Defragger{}}
		b.ReportAllocs()
		b.SetBytes(int64(len(msg)))
		for b.Loop() {
			if _, _, err := r.ReadFrom(p); err != nil {
				b.Fatal(err)
			}
		}
	})
}

func BenchmarkReadMultiBuffer(b *testing.B) {
	msg := benchMessage()
	b.Run("old", func(b *testing.B) {
		r := &oldUDPReader{reader: &repeatReader{msg: msg}, df: &Defragger{}}
		b.ReportAllocs()
		b.SetBytes(int64(len(msg)))
		for b.Loop() {
			mb, err := r.ReadMultiBuffer()
			if err != nil {
				b.Fatal(err)
			}
			mb[0].Release()
		}
	})
	b.Run("new", func(b *testing.B) {
		r := &UDPReader{reader: &repeatReader{msg: msg}, df: &Defragger{}}
		b.ReportAllocs()
		b.SetBytes(int64(len(msg)))
		for b.Loop() {
			mb, err := r.ReadMultiBuffer()
			if err != nil {
				b.Fatal(err)
			}
			mb[0].Release()
		}
	})
}

func TestAllocCounts(t *testing.T) {
	msg := benchMessage()
	p := make([]byte, 65535)
	bufr := buf.FromBytes(make([]byte, 1200))
	dest, err := xnet.ParseDestination("udp:" + benchAddr)
	if err != nil {
		t.Fatal(err)
	}
	bufr.UDP = &dest
	mb := buf.MultiBuffer{bufr}

	oldW := &oldUDPWriter{writer: io.Discard, addr: benchAddr}
	newW := &UDPWriter{writer: io.Discard, addr: benchAddr}
	oldR := &oldUDPReader{reader: &repeatReader{msg: msg}, df: &Defragger{}}
	newR := &UDPReader{reader: &repeatReader{msg: msg}, df: &Defragger{}}

	report := func(name string, n float64) { t.Logf("%-24s %.1f allocs/op", name, n) }
	report("parse old", testing.AllocsPerRun(1000, func() { oldParse(msg) }))
	report("parse new", testing.AllocsPerRun(1000, func() { ParseUDPMessage(msg) }))
	report("parse new reuse addr", testing.AllocsPerRun(1000, func() {
		ParseUDPMessageReuseAddr(msg, benchAddr)
	}))
	report("write old", testing.AllocsPerRun(1000, func() { oldW.WriteMultiBuffer(mb) }))
	report("write new", testing.AllocsPerRun(1000, func() { newW.WriteMultiBuffer(mb) }))
	report("read old", testing.AllocsPerRun(1000, func() { oldR.ReadFrom(p) }))
	report("read new", testing.AllocsPerRun(1000, func() { newR.ReadFrom(p) }))
	report("read mb old", testing.AllocsPerRun(1000, func() {
		mb, _ := oldR.ReadMultiBuffer()
		mb[0].Release()
	}))
	report("read mb new", testing.AllocsPerRun(1000, func() {
		mb, _ := newR.ReadMultiBuffer()
		mb[0].Release()
	}))
}
